def is_mirror_word(word):
    # Define the mapping of characters to their mirror reflections
    mirror_map = {
        'A': 'A', 'B': '', 'C': '', 'D': '', 'E': '3', 'F': '', 'G': '',
        'H': 'H', 'I': 'I', 'J': '', 'K': '', 'L': '', 'M': 'M',
