        'U': 'U', 'V': 'V', 'W': '', 'X': 'X', 'Y': 'y', 'Z': ''
    }

    # Check if all characters have valid mirror reflections
    for char in word:
        if char not in mirror_map:
            return 'NO'

    # Construct the mirrored version of the word
